private val taps = MutableSharedFlow<Message>(
    extraBufferCapacity = 1024)   // default SUSPEND: tryEmit never suspends, false == would-block
private val dropped = AtomicLong()

suspend fun handle(m: Message, primary: suspend (Message) -> Unit) {
    if (!taps.tryEmit(m.snapshot())) dropped.incrementAndGet()  // best-effort copy, counted
    primary(m)                       // original instance, unchanged, untimed by the tap
}

// analyzer attaches and detaches without touching sender or receiver:
val tapJob = scope.launch(Dispatchers.IO) { taps.collect { analyze(it) } }
